        old = subprocess.check_output(['git','show',parent+':'+path],text=True).splitlines()
        new = Path(path).read_text().splitlines()
        if name == 'owner-sessions.jsonl':
            oldkeys = {json.loads(line)['name'] for line in old if line}
            newkeys = {json.loads(line)['name'] for line in new if line}
            print(name, 'missing session identities:', sorted(oldkeys-newkeys))
        else:
            print(name, 'missing exact records:',len(set(old)-set(new)))
